import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminDashboard.css";   // reutiliza el grid y estilos
import VideoStream from "./VideoStream";

export default function Dashboard({ onBack }) {
  const [time, setTime] = useState(new Date());
  const [passengerCount, setPassengerCount] = useState(0);
  const capacity = 30;
  const navigate = useNavigate();

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const status =
    passengerCount > capacity
      ? "Sobreaforo"
      : passengerCount === capacity
      ? "Lleno"
      : "OK";

  const handleBack = () => {
    if (onBack) onBack(navigate);
    else navigate("/login");
  };

  return (
    <div className="admin-parent">
      {/* Navbar simplificado para usuario */}
      <div className="div3">
        <div className="nav-bar">
          <button className="nav-left" onClick={handleBack}>
            ← Inicio
          </button>
          <h2 className="nav-title">Dashboard</h2>
          <div className="nav-right">CPATBUS</div>
        </div>
      </div>

      {/* Mapa de buses */}
      <div className="div4">
        <iframe
          src="https://zenbus.net/publicapp/limasanisidromibus77868410?line=677150016"
          title="Mapa de Buses"
        />
      </div>

      {/* Vídeo en vivo */}
      <div className="div5">
        <VideoStream />
      </div>

      {/* Reloj */}
      <div className="div7">
        <p className="clock">{time.toLocaleTimeString()}</p>
        <p className="date">{time.toLocaleDateString()}</p>
      </div>

      {/* Datos y conteo */}
      <div className="div8">
        <h3>Datos del Bus</h3>
        <ul>
          <li><strong>Capacidad:</strong> {capacity}</li>
          <li><strong>Pasajeros:</strong> {passengerCount}</li>
          <li><strong>Estado:</strong> {status}</li>
        </ul>
      </div>
    </div>
  );
}
